// Most runs have nothing to do. A Postgres node with alwaysOutputData emits one EMPTY item
// for zero rows, which would reach the sender as a malformed notice — drop it here. This node
// must NOT set alwaysOutputData, or an empty return becomes an empty item all over again.
return $input.all().filter(i => (i.json || {}).appointment_id !== undefined);

// One line per notice handled, so a scheduler run is auditable at a glance.
const sent = $input.all().map(i => i.json || {});
const by = sent.reduce((a, s) => { const k = s.reason || 'unknown'; a[k] = (a[k] || 0) + 1; return a; }, {});
return [{ json: { ran_at: new Date().toISOString(), notices: sent.length, by_outcome: by,
                  detail: sent.map(s => `${s.recipient}/${s.kind}#${s.appointment_id}:${s.reason}`) } }];
